function stdSubs(driveReg, volReg) {
  return [
    { id: "origin", label: "\u539F\u5473", regDeltas: {} },
    { id: "bright", label: "\u660E\u4EAE", regDeltas: { [driveReg]: 3, [volReg]: 2 } },
    { id: "thick", label: "\u80A5\u539A", regDeltas: { [driveReg]: -3, [volReg]: -1 } }
  ];
}
