var DRIVE_REG = { overdrive: 49, dist: 64 };
var VOL_REG = { overdrive: 51, dist: 66 };
var DRIVE_KNOB_CANDIDATES = ["DRIVE", "GAIN", "DISTORTION", "SUSTAIN"];
var VOL_KNOB_CANDIDATES = ["LEVEL", "VOLUME", "OUTPUT"];
function knobsFromRegDeltas(baseKnobs, moduleId, regDeltas) {
  const out = { ...baseKnobs };
  for (const [addrStr, delta] of Object.entries(regDeltas)) {
    const addr = Number(addrStr);
    let candidates = [];
    let normRange = 1;
    if (addr === DRIVE_REG[moduleId]) {
      candidates = DRIVE_KNOB_CANDIDATES;
      normRange = 92;
    } else if (addr === VOL_REG[moduleId]) {
      candidates = VOL_KNOB_CANDIDATES;
      normRange = 40;
    }
    const label = candidates.find((k) => k in out);
    if (label) out[label] = Math.max(0, Math.min(1, out[label] + delta / normRange));
  }
  return out;
}
for (const s of SERIES_REGISTRY) {
  const base = OVERDRIVE_DEFAULTS[s.baseKey];
  if (!base) throw new Error(`[seriesData] baseKey \u7F3A\u5931: ${s.baseKey} (${s.uiName})`);
  for (const so of s.subOptions) {
    const allRegs = { ...base.allRegs };
    for (const [addrStr, delta] of Object.entries(so.regDeltas)) {
      const addr = Number(addrStr);
      allRegs[addr] = Math.max(0, Math.min(288, (allRegs[addr] ?? 0) + delta));
    }
    OVERDRIVE_DEFAULTS[seriesComposedKey(s, so)] = {
      knobs: { ...knobsFromRegDeltas(base.knobs, s.moduleId, so.regDeltas), ...so.knobs ?? {} },
      hidden: { ...base.hidden },
      allRegs
    };
  }
}
