for (const s of SERIES_REGISTRY) {
  for (const so of s.subOptions) {
    const key = seriesComposedKey(s, so);
    const formula = SUB_MODEL_FORMULAS[s.baseKey];
    if (formula) SUB_MODEL_FORMULAS[key] = formula;
    const basePre = SUB_MODEL_PRE_EQ[s.baseKey];
    if (basePre) {
      SUB_MODEL_PRE_EQ[key] = {
        regs: basePre.regs,
        bypass: basePre.bypass,
        values: so.preEq ?? basePre.values
      };
    }
  }
}
var RATIO_INDEX_TABLE = [1, 1.2, 1.4, 1.6, 1.8, 2, 2.4, 2.8, 3.2, 3.6, 4, 4.4, 4.8, 5.2, 5.6, 6, 6.4, 6.8, 7.2, 7.6, 8, 8.4, 9, 9.6, 10.2, 10.8, 11.4, 12, 13, 14, 15, 16, 17, 18, 19, 20, 22, 24, 26, 30, 100];
function ratioToIndex(target) {
  let best = 0, bestD = Infinity;
  for (let i = 0; i < RATIO_INDEX_TABLE.length; i++) {
    const d = Math.abs(RATIO_INDEX_TABLE[i] - target);
    if (d < bestD) {
      bestD = d;
      best = i;
    }
  }
  return best;
}

// src/data/overdriveBoost.ts
var isNamModel = (name) => !!name && (name.startsWith("NAM") || name.startsWith("B&F NAM") || !!SERIES_BY_COMPOSED[name]);

