    regs2.push({ regAddr: 54, value: buildPEQData(PEQ_TYPE.PEAK, 300, 120, 16, 10), label: "OD Post2" });
    regs2.push({ regAddr: 55, value: buildPEQData(PEQ_TYPE.PEAK, 500, 120, 16, 10), label: "OD Post3" });
    regs2.push({ regAddr: 56, value: buildPEQData(PEQ_TYPE.PEAK, 800, 120, 16, 10), label: "OD Post4" });
