var MODULES = [
  noiseGate,
  boost,
  compressor,
  overdrive,
  dist,
  ampHead,
  cabinet,
  chorus,
  delay,
  reverb
];
function getSubModels(module, mode) {
  if (!module.hasSubModels || !module.subModels) return [];
  return mode === "guitar" ? module.subModels.guitar ?? [] : module.subModels.bass ?? [];
}
function getDefaultSubModelName(sm) {
  if (sm.captures?.length) return `${sm.name}/${sm.captures[0].pos}`;
  return sm.name;
}

// tools/_verify_series.ts
var fails = 0;
var check = (cond, msg) => {
  if (!cond) {
    fails++;
    console.error("FAIL:", msg);
  }
};
for (const s of SERIES_REGISTRY) {
  check(!!OVERDRIVE_DEFAULTS[s.baseKey], `baseKey missing: ${s.baseKey}`);
  check(!!SUB_MODEL_FORMULAS[s.baseKey], `formula missing: ${s.baseKey}`);
  check(!!SUB_MODEL_PRE_EQ[s.baseKey], `preeq missing: ${s.baseKey}`);
  check(s.subOptions.length === 3, `subOptions !=3: ${s.uiName}`);
  for (const so of s.subOptions) {
    const key = seriesComposedKey(s, so);
    check(!!OVERDRIVE_DEFAULTS[key], `series OD missing: ${key}`);
    check(!!SUB_MODEL_FORMULAS[key], `series formula missing: ${key}`);
    check(!!SUB_MODEL_PRE_EQ[key], `series preeq missing: ${key}`);
    check(isNamModel(key), `isNamModel false: ${key}`);
    check(!!SERIES_BY_COMPOSED[key], `SERIES_BY_COMPOSED missing: ${key}`);
    check(key.split("/").length === 2, `composed key split !=2: ${key}`);
  }
}
var odMod = MODULES.find((m) => m.id === "overdrive");
var distMod = MODULES.find((m) => m.id === "dist");
var odG = getSubModels(odMod, "guitar");
var odB = getSubModels(odMod, "bass");
var dG = getSubModels(distMod, "guitar");
var dB = getSubModels(distMod, "bass");
check(odG.length === 6, `OD guitar count ${odG.length}`);
check(odB.length === 3, `OD bass count ${odB.length}`);
check(dG.length === 5, `DIST guitar count ${dG.length}`);
check(dB.length === 1, `DIST bass count ${dB.length}`);
for (const m of [...odG, ...odB, ...dG, ...dB]) {
  check(m.captures?.length === 3, `captures !=3: ${m.name}`);
  const def = getDefaultSubModelName(m);
  check(!!OVERDRIVE_DEFAULTS[def], `default combo not materialized: ${def}`);
  check(def === `${m.name}/${m.captures[0].pos}`, `default combo shape: ${def}`);
}
var s0 = SERIES_REGISTRY[0];
var ds = SERIES_REGISTRY.find((s) => s.moduleId === "dist" && s.mode === "guitar");
var regs = generatePresetRegisters(
  "t",
  "t",
  "guitar",
  { overdrive: true, dist: true, "amp-head": false, overdriveSubModel: seriesComposedKey(s0, s0.subOptions[1]), distSubModel: seriesComposedKey(ds, ds.subOptions[0]) },
  void 0
);
var odW = regs.filter((r) => r.regAddr >= 42 && r.regAddr <= 56);
var dW = regs.filter((r) => r.regAddr >= 57 && r.regAddr <= 71);
check(odW.length > 0, "no OD writes");
check(dW.length > 0, "no DIST writes");
console.log("OD writes:", odW.length, "| DIST writes:", dW.length);
var oK = OVERDRIVE_DEFAULTS[seriesComposedKey(s0, s0.subOptions[0])];
var bK = OVERDRIVE_DEFAULTS[seriesComposedKey(s0, s0.subOptions[1])];
var tK = OVERDRIVE_DEFAULTS[seriesComposedKey(s0, s0.subOptions[2])];
console.log(`\u4E2D\u9891\u8FC7\u8F7D drive reg: \u539F\u5473=${oK.allRegs[49]} \u660E\u4EAE=${bK.allRegs[49]} \u80A5\u539A=${tK.allRegs[49]}`);
console.log(`\u4E2D\u9891\u8FC7\u8F7D drive knob: \u539F\u5473=${oK.knobs.DRIVE} \u660E\u4EAE=${bK.knobs.DRIVE} \u80A5\u539A=${tK.knobs.DRIVE}`);
check(bK.allRegs[49] > oK.allRegs[49] && tK.allRegs[49] < oK.allRegs[49], "bright/thick drive order");
check(bK.knobs.DRIVE > oK.knobs.DRIVE && tK.knobs.DRIVE < oK.knobs.DRIVE, "bright/thick knob order");
check(Math.round(bK.knobs.DRIVE * 92) === bK.allRegs[49], `knob/reg mismatch bright (${Math.round(bK.knobs.DRIVE * 92)} vs ${bK.allRegs[49]})`);
var dOri = OVERDRIVE_DEFAULTS[seriesComposedKey(ds, ds.subOptions[0])];
var dBri = OVERDRIVE_DEFAULTS[seriesComposedKey(ds, ds.subOptions[1])];
console.log(`\u7ECF\u5178\u5931\u771F drive reg: \u539F\u5473=${dOri.allRegs[64]} \u660E\u4EAE=${dBri.allRegs[64]}`);
check(dBri.allRegs[64] > dOri.allRegs[64], "dist bright drive order");
if (fails) {
  console.error(`${fails} FAILURES`);
  process.exit(1);
}
